Tool response:
Tool: bulk_reassign_assets
Description: Bulk Reassign Assets
Parameters:
    {
      "type": "object",
      "properties": {
        "current_location_name": {
          "type": "string",
          "description": "Name of the current location to filter assets",
          "title": "Current Location Name"
        },
        "current_custodian_name": {
          "type": "string",
          "description": "Name of the current custodian to filter assets",
          "title": "Current Custodian Name"
        },
        "new_location_name": {
          "type": "string",
          "description": "Name of the new location to assign assets to",
          "title": "New Location Name"
        },
        "new_custodian_name": {
          "type": "string",
          "description": "Name of the new custodian to assign assets to",
          "title": "New Custodian Name"
        }
      },
      "required": [
        "current_location_name",
        "current_custodian_name",
        "new_location_name",
        "new_custodian_name"
      ]
    }
